//! Compares heading ids and footnotes with the output of Comark itself.
//!
//! `tests/fixtures/comark.json` is generated by `scripts/comark_fixtures.mjs`.

use oxmark::{to_html_with, HtmlOptions, Options};

/// Comark pretty-prints its HTML and writes void tags without a slash.
fn normalize(html: &str) -> String {
    html.lines()
        .map(str::trim)
        .collect::<String>()
        .replace(" />", ">")
}

#[test]
fn matches_comark() {
    let value: serde_json::Value =
        serde_json::from_str(include_str!("fixtures/comark.json")).unwrap();
    let mut failures = Vec::new();
    for case in value.as_array().unwrap() {
        let options = Options {
            footnotes: case["footnotes"].as_bool().unwrap(),
            ..Options::default()
        };
        let markdown = case["markdown"].as_str().unwrap();
        let expected = case["html"].as_str().unwrap();
        let actual = to_html_with(markdown, &options, &HtmlOptions::default());
        if normalize(&actual) != normalize(expected) {
            failures.push(format!(
                "{}\n--- expected\n{expected}\n--- actual\n{actual}",
                case["name"]
            ));
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n\n"));
}

fn footnotes(md: &str) -> String {
    let options = Options {
        footnotes: true,
        ..Options::default()
    };
    to_html_with(md, &options, &HtmlOptions::default())
}

#[test]
fn undefined_footnotes_are_spans() {
    // An undefined footnote is a span, as in Comark.
    assert_eq!(footnotes("Text[^b]."), "<p>Text<span>^b</span>.</p>\n");
    assert_eq!(
        to_html_with(
            "Text[^a].\n\n[^a]: x",
            &Options::default(),
            &HtmlOptions::default()
        ),
        // Without the extension, `[^a]` is a Comark span, as in Comark.
        "<p>Text<span>^a</span>.</p>\n"
    );
}

#[test]
fn footnote_definitions_hold_inline_markdown() {
    let html = footnotes("A[^n].\n\n[^n]: Some *emphasis* and a [link](https://example.com).");
    assert!(html.contains(
        "<li id=\"fn-n\">Some <em>emphasis</em> and a <a href=\"https://example.com\">link</a>. <a href=\"#fnref-n\""
    ), "{html}");
}

#[test]
fn repeated_footnote_references_get_unique_ids() {
    let html = footnotes("A[^n] B[^n].\n\n[^n]: x");
    assert!(html.contains("id=\"fnref-n\">[1]"), "{html}");
    assert!(html.contains("id=\"fnref-n-2\">[1]"), "{html}");
    assert_eq!(html.matches("<li").count(), 1);
}

#[test]
fn footnotes_in_the_ast() {
    let options = Options {
        footnotes: true,
        ..Options::default()
    };
    let doc = oxmark::parse_with(
        "A[^b] C[^a] D[^b].\n\n[^a]: first\n[^b]: second\n[^c]: unused",
        &options,
    );
    let labels: Vec<_> = doc
        .footnotes
        .iter()
        .map(|f| (f.label.as_ref(), f.index, f.references))
        .collect();
    assert_eq!(labels, [("b", 1, 2), ("a", 2, 1)]);
    // The definitions do not leave an empty paragraph behind.
    assert_eq!(doc.children.len(), 1);
}

#[test]
fn heading_ids_can_be_disabled() {
    let options = Options {
        heading_ids: false,
        ..Options::default()
    };
    assert_eq!(
        to_html_with("# Title", &options, &HtmlOptions::default()),
        "<h1>Title</h1>\n"
    );
}
